$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$repoRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $repoRoot

function Invoke-Git {
    param(
        [Parameter(Mandatory = $true)]
        [string[]]$Args
    )

    & git @Args
    if ($LASTEXITCODE -ne 0) {
        throw "Git command failed: git $($Args -join ' ')"
    }
}

$bundleBase64 = @'

'@

$tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) ("raskrutov-skills-" + [Guid]::NewGuid().ToString("N"))
$tempZip = Join-Path $tempRoot "skills.zip"
$tempExtract = Join-Path $tempRoot "extract"

New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null
New-Item -ItemType Directory -Path $tempExtract -Force | Out-Null

try {
    [System.IO.File]::WriteAllBytes(
        $tempZip,
        [System.Convert]::FromBase64String($bundleBase64)
    )

    Expand-Archive -Path $tempZip -DestinationPath $tempExtract -Force

    $sourceSkills = Join-Path $tempExtract ".agents\skills"
    if (-not (Test-Path $sourceSkills)) {
        throw "Embedded bundle does not contain .agents\skills"
    }

    $targetAgents = Join-Path $repoRoot ".agents"
    $targetSkills = Join-Path $targetAgents "skills"

    New-Item -ItemType Directory -Path $targetAgents -Force | Out-Null
    New-Item -ItemType Directory -Path $targetSkills -Force | Out-Null

    Copy-Item -Path (Join-Path $sourceSkills "*") -Destination $targetSkills -Recurse -Force

    $skillFiles = @(
        Get-ChildItem $targetSkills -Recurse -Filter "SKILL.md" -File
    )

    $referenceFiles = @(
        Get-ChildItem $targetSkills -Recurse -File |
            Where-Object { $_.FullName -match "\\references\\" }
    )

    Write-Host "SKILL.md files found: $($skillFiles.Count)"
    Write-Host "Reference files found: $($referenceFiles.Count)"

    if ($skillFiles.Count -ne 13) {
        throw "Expected 13 SKILL.md files, found $($skillFiles.Count)"
    }

    if ($referenceFiles.Count -ne 4) {
        throw "Expected 4 reference files, found $($referenceFiles.Count)"
    }

    Invoke-Git -Args @("add", "--", ".agents/skills")

    & git diff --cached --quiet -- .agents/skills
    $diffExitCode = $LASTEXITCODE

    if ($diffExitCode -eq 0) {
        Write-Host "Skills are already installed. Nothing to commit."
        exit 0
    }

    if ($diffExitCode -ne 1) {
        throw "Unable to inspect staged skill changes."
    }

    Invoke-Git -Args @(
        "commit",
        "-m",
        "feat: add complete project agent skills bundle"
    )

    Invoke-Git -Args @("push", "origin", "main")

    Write-Host ""
    Write-Host "Done. Published 13 skills and 4 reference files."
}
finally {
    if (Test-Path $tempRoot) {
        Remove-Item $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
    }
}
